 12723          case XML_ATTRIBUTE_NODE:
 12724          case XML_TEXT_NODE:
 12725          case XML_CDATA_SECTION_NODE:
 12726          case XML_ENTITY_REF_NODE:
 12727          case XML_PI_NODE:
 12728          case XML_COMMENT_NODE:
 12729          case XML_DOCUMENT_NODE:
 12730          case XML_HTML_DOCUMENT_NODE:
 12731              break;
 12732          default:
